// All effect-group members ON — the fallback when a stale caller sends a
// WeatherFxState without the W3 `effects` map (preserves legacy W2 behavior).
const WEATHER_ALL_EFFECTS: Record<WeatherEffectKey, boolean> = {
  precip: true, fog: true, lightning: true, wind: true, clouds: true,
  sunPosition: true, sunDisc: true, frost: true, puddles: true, precipForecast: true,
};

// Phase 3 sky-backdrop condition sets. DIM = conditions that grey-out / darken
// the dome (and dim the sun/moon disc); WET = precip conditions that darken it
// further. Used by ThreeDRenderer._skyColorsFor / _overcastAmt.
const WEATHER_DIM_SKY = new Set<string>([
  'cloudy', 'rainy', 'pouring', 'snowy', 'snowy-rainy', 'hail',
  'lightning', 'lightning-rainy', 'fog', 'exceptional',
]);
const WEATHER_WET_SKY = new Set<string>([
  'rainy', 'pouring', 'snowy-rainy', 'hail', 'lightning-rainy',
]);
// Below this the (1 − dayness) star ramp is visually zero. The dayness ease is
// exponential and asymptotes rather than landing on 0, so the whole night-sky
// group (decorative starfield / catalog stars / constellation lines / planets)
// flips `visible = false` here instead of drawing near-invisible geometry in
// broad daylight. Exported for the sky test pages.
export const STAR_RAMP_MIN = 0.02;

// What a 3D pick surfaces. `kind` is the userData tag the raycast walker found
// on the nearest hit's first tagged ancestor; three-view routes on it. Most
// kinds resolve a per-floor fixture by `fixtureId`; 'flight' is the outlier —
// an ADS-B aircraft is not a placed fixture, so it carries `hex` (its ICAO
// address, also mirrored into fixtureId so the shape stays uniform) and never
// an entity_id.
export type FixtureClickKind =
  | 'light' | 'switch' | 'media' | 'alarm' | 'thermostat' | 'safety' | 'alert'
  | 'robot' | 'lock' | 'appliance' | 'action' | 'projector' | 'valve' | 'plug'
  | 'sprinkler' | 'flight';
export interface FixtureClickInfo {
  kind: FixtureClickKind;
  entity_id: string | null;
  fixtureId: string;
  hex?: string;          // 'flight' only — the aircraft's ICAO 24-bit address
}
// The single source of truth the raycast walker tests against (adding a kind to
// the union above and forgetting the walker was the old failure mode).
const FIXTURE_CLICK_KINDS = new Set<string>([
  'light', 'switch', 'media', 'alarm', 'thermostat', 'safety', 'alert', 'robot',
  'lock', 'appliance', 'action', 'projector', 'valve', 'plug', 'sprinkler', 'flight',
]);

